package com.cpf.starter.rabbitmq;
import java.time.Duration;
import org.springframework.boot.context.properties.ConfigurationProperties;
@ConfigurationProperties("cpf.messaging.rabbitmq")
public class CpfRabbitMqProperties {private boolean enabled;private String bindingName="rabbitmq";private boolean defaultBinding;private String exchange;private String exchangeType="topic";private String queue;private String routingKey="#";private boolean durable=true;private boolean quorum=true;private int prefetch=50;private int concurrency=1;private int maxPayloadBytes=1048576;private Duration confirmTimeout=java.time.Duration.ofSeconds(10);
 public boolean isEnabled(){return enabled;}public void setEnabled(boolean v){enabled=v;}public String getBindingName(){return bindingName;}public void setBindingName(String v){bindingName=v;}public boolean isDefaultBinding(){return defaultBinding;}public void setDefaultBinding(boolean v){defaultBinding=v;}public String getExchange(){return exchange;}public void setExchange(String v){exchange=v;}public String getExchangeType(){return exchangeType;}public void setExchangeType(String v){exchangeType=v;}public String getQueue(){return queue;}public void setQueue(String v){queue=v;}public String getRoutingKey(){return routingKey;}public void setRoutingKey(String v){routingKey=v;}public boolean isDurable(){return durable;}public void setDurable(boolean v){durable=v;}public boolean isQuorum(){return quorum;}public void setQuorum(boolean v){quorum=v;}public int getPrefetch(){return prefetch;}public void setPrefetch(int v){prefetch=v;}public int getConcurrency(){return concurrency;}public void setConcurrency(int v){concurrency=v;}public int getMaxPayloadBytes(){return maxPayloadBytes;}public void setMaxPayloadBytes(int v){maxPayloadBytes=v;}public Duration getConfirmTimeout(){return confirmTimeout;}public void setConfirmTimeout(Duration v){confirmTimeout=v;}
 public void validate(){if(!enabled)return;if(bindingName==null||bindingName.isBlank()||exchange==null||exchange.isBlank()||queue==null||queue.isBlank())throw new IllegalStateException("binding-name, exchange and queue are required");if(!java.util.Set.of("direct","topic","fanout","headers").contains(exchangeType))throw new IllegalStateException("Unsupported exchange-type");if(prefetch<1||concurrency<1||maxPayloadBytes<1)throw new IllegalStateException("prefetch, concurrency and max-payload-bytes must be positive");}}
